// Provide handlers through an async getter so MSW (ESM) is imported at runtime
export async function getHandlers() {
  console.log("handlers.getHandlers: called");
  const msw = await import("msw");
  // Use the `http` helper from the core package which is available
  // (it provides http.get/http.post similar to `rest` helpers)
  const { rest } = msw as any;

  const handlers = [
    rest.get("/api/qmoi/status", (req: any, res: any, ctx: any) => {
      return res(
        ctx.status(200),
        ctx.json({
          status: "OK",
          last_check: "2024-06-01T12:00:00Z",
          mutation_count: 5,
          logs: ["Log 1", "Log 2"],
        })
      );
    }),
    rest.post("/api/qmoi/payload", (req: any, res: any, ctx: any) => {
      // in rest handlers, req.url is a URL instance
      const action = req.url.searchParams.get("qfix")
        ? "QFix"
        : req.url.searchParams.get("qoptimize")
        ? "QOptimize"
        : req.url.searchParams.get("qsecure")
        ? "QSecure"
        : "Unknown";
      return res(ctx.status(200), ctx.json({ message: `${action} done` }));
    }),
  ];
  console.log("handlers.getHandlers: returning", handlers.length);
  return handlers;
}
